def comps_of_2x2(I,b0):
    cells={(b0[0]+dy,b0[1]+dx) for dy in(0,1) for dx in(0,1)}
    res=[]
    while len(cells)>len(res):
        if len(res)==len(cells): break
        stack=[next(iter(cells))]; seen={}; comp=[]
        while stack:
            x,y=stack.pop()
            if (x,y) in seen: continue
            seen.add((x,y)); comp.append((x,y))
            for dy in(-1,0,1):
